@GameTestHolder("jdte") @PrefixGameTestTemplate(false)
public final class TimeMultitoolGameTests {
    private static final BlockPos P=new BlockPos(2,2,2);
    private static TimeMultitoolItem tool(){return JDTEItems.TIME_MULTITOOL.get();}
    public static ItemStack charged(int energy,int fluid,TimeMultitoolSpeedMode mode){var s=new ItemStack(JDTEItems.TIME_MULTITOOL.get());s.getCapability(ForgeCapabilities.ENERGY).orElseThrow(AssertionError::new).receiveEnergy(energy,false);s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElseThrow(AssertionError::new).fill(new FluidStack(Registration.TIME_FLUID_SOURCE.get(),fluid),IFluidHandler.FluidAction.EXECUTE);TimeMultitoolSpeedStorage.set(s,mode);return s;}
    public static ServerPlayer actor(GameTestHelper h,ItemStack stack){var p=FakePlayerFactory.get(h.getLevel(),new GameProfile(UUID.randomUUID(),"TimeToolTest"));p.gameMode.changeGameModeForPlayer(GameType.SURVIVAL);p.getInventory().clearContent();p.setItemInHand(InteractionHand.MAIN_HAND,stack);p.setPos(Vec3.atCenterOf(h.absolutePos(P)).add(0,2,0));p.setXRot(90);return p;}
    private static int fe(ItemStack s){return s.getCapability(ForgeCapabilities.ENERGY).orElseThrow(AssertionError::new).getEnergyStored();}
    private static int fluid(ItemStack s){return FluidContainingItem.getAvailableFluid(s);}
    private static void upgrade(ItemStack s,Ability a){s.getOrCreateTag().putBoolean("upgrade_"+a.getName(),true);ToggleableTool.setSetting(s,a.getName(),true);}
    private static List<net.minecraft.world.entity.item.ItemEntity> drops(GameTestHelper h){return h.getLevel().getEntitiesOfClass(net.minecraft.world.entity.item.ItemEntity.class,new AABB(h.absolutePos(P)).inflate(5));}
    @GameTest(template="mineral_empty") public static void realGameModeBreakPaysOnceAndLastFeStillDrops(GameTestHelper h){
        var s=charged(50,2,TimeMultitoolSpeedMode.TWO);var p=actor(h,s);h.setBlock(P,Blocks.STONE);h.assertTrue(p.gameMode.destroyBlock(h.absolutePos(P)),"actual Forge game-mode removal succeeded");h.assertTrue(h.getBlockState(P).isAir()&&fe(s)==0&&fluid(s)==0,"exact last50FE and2mB once");h.assertTrue(drops(h).stream().filter(e->e.getItem().is(Items.COBBLESTONE)).mapToInt(e->e.getItem().getCount()).sum()==1,"depleted tool still gets its correctly harvested original drop");var beforeDrops=drops(h).stream().map(e->e.getItem().save(new CompoundTag())).toList();h.assertTrue(!p.gameMode.destroyBlock(h.absolutePos(P))&&fe(s)==0&&beforeDrops.equals(drops(h).stream().map(e->e.getItem().save(new CompoundTag())).toList()),"duplicate request cannot remove, charge or change any existing drop again");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void emptyEnergyAndInsufficientFluidHaveSourceFallbacks(GameTestHelper h){
        var s=charged(49,100,TimeMultitoolSpeedMode.TWO);var p=actor(h,s);h.setBlock(P,Blocks.STONE);h.assertTrue(!p.gameMode.destroyBlock(h.absolutePos(P))&&fe(s)==49&&fluid(s)==100&&h.getBlockState(P).is(Blocks.STONE),"unpowered source tool cannot break or spend fluid");s.getCapability(ForgeCapabilities.ENERGY).orElseThrow(AssertionError::new).receiveEnergy(100,false);s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElseThrow(AssertionError::new).drain(99,IFluidHandler.FluidAction.EXECUTE);h.assertTrue(p.gameMode.destroyBlock(h.absolutePos(P))&&fe(s)==99&&fluid(s)==1,"less than2mB falls back to1x without partial fluid payment");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void modeCycleAndNbtRoundTripRetainNativeSettings(GameTestHelper h){
        var s=charged(12345,9876,TimeMultitoolSpeedMode.ONE);var p=actor(h,s);p.setShiftKeyDown(true);int[] modes={2,4,16,256,1024,1};for(int mode:modes){tool().use(h.getLevel(),p,InteractionHand.MAIN_HAND);h.assertTrue(TimeMultitoolItem.getSelectedSpeedMode(s).multiplier()==mode,"server air-use mode cycle");}upgrade(s,Ability.HAMMER);s.setHoverName(net.minecraft.network.chat.Component.literal("Saved time tool"));var saved=s.save(new CompoundTag());var copy=ItemStack.of(saved);h.assertTrue(saved.equals(copy.save(new CompoundTag()))&&fe(copy)==12345&&fluid(copy)==9876&&tool().canUseAbility(copy,Ability.HAMMER),"mode/FE/fluid/native upgrades/name full NBT roundtrip");copy.getOrCreateTag().putInt(TimeMultitoolSpeedStorage.KEY,Integer.MAX_VALUE);h.assertTrue(TimeMultitoolItem.getSelectedSpeedMode(copy)==TimeMultitoolSpeedMode.ONE,"invalid stored mode safely defaults to1x");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void realHammerBatchBudgetsWholeFluidThenChargesSuccessfulBlocks(GameTestHelper h){
        for(boolean enough:new boolean[]{false,true}){var s=charged(5000,enough?18:17,TimeMultitoolSpeedMode.TWO);upgrade(s,Ability.HAMMER);var p=actor(h,s);for(var pos:BlockPos.betweenClosed(P.offset(-1,0,-1),P.offset(1,0,1)))h.setBlock(pos,Blocks.STONE);var targets=tool().getBreakBlockPositions(s,h.getLevel(),h.absolutePos(P),p,h.getBlockState(P));h.assertTrue(targets.size()==9,"actual native-oriented3x3 hammer selection");h.assertTrue(p.gameMode.destroyBlock(h.absolutePos(P))&&fe(s)==4550&&fluid(s)==(enough?0:17),"nine real removals pay450FE and exact full batch bonus or no fluid");}h.succeed();
    }
    @GameTest(template="mineral_empty") public static void insufficientFeStopsHammerWithoutFreeExtraRemoval(GameTestHelper h){
        var s=charged(50,18,TimeMultitoolSpeedMode.TWO);upgrade(s,Ability.HAMMER);var p=actor(h,s);for(var pos:BlockPos.betweenClosed(P.offset(-1,0,-1),P.offset(1,0,1)))h.setBlock(pos,Blocks.STONE);p.gameMode.destroyBlock(h.absolutePos(P));long remaining=BlockPos.betweenClosedStream(h.absolutePos(P.offset(-1,0,-1)),h.absolutePos(P.offset(1,0,1))).filter(pos->h.getLevel().getBlockState(pos).is(Blocks.STONE)).count();h.assertTrue(remaining==8&&fe(s)==0&&fluid(s)==16,"only paid primary removed when FE exhausts; unused batch fluid preserved");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void cancelledPrimaryAndCancelledSecondaryConserveResources(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);var p=actor(h,s);h.setBlock(P,Blocks.STONE);var original=s.save(new CompoundTag());Consumer<BlockEvent.BreakEvent> denied=e->{if(e.getPlayer()==p)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(denied);try{h.assertTrue(!p.gameMode.destroyBlock(h.absolutePos(P)),"real Forge cancellation rejects removal");}finally{MinecraftForge.EVENT_BUS.unregister(denied);}h.assertTrue(original.equals(s.save(new CompoundTag()))&&h.getBlockState(P).is(Blocks.STONE),"cancelled event spends no FE/fluid and produces no drops");
        upgrade(s,Ability.HAMMER);for(var pos:BlockPos.betweenClosed(P.offset(-1,0,-1),P.offset(1,0,1)))h.setBlock(pos,Blocks.STONE);var blocked=h.absolutePos(P.east());Consumer<BlockEvent.BreakEvent> one=e->{if(e.getPlayer()==p&&e.getPos().equals(blocked))e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(one);try{p.gameMode.destroyBlock(h.absolutePos(P));}finally{MinecraftForge.EVENT_BUS.unregister(one);}h.assertTrue(fe(s)==600&&fluid(s)==84&&h.getLevel().getBlockState(blocked).is(Blocks.STONE),"eight successes only:400FE/16mB; denied secondary is intact");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void replacedTargetAndChangedHeldToolCannotSpendOldResources(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);var p=actor(h,s);h.setBlock(P,Blocks.STONE);var original=s.save(new CompoundTag());Consumer<BlockEvent.BreakEvent> replaced=e->{if(e.getPlayer()==p)h.setBlock(P,Blocks.GOLD_BLOCK);};MinecraftForge.EVENT_BUS.addListener(replaced);try{h.assertTrue(!p.gameMode.destroyBlock(h.absolutePos(P)),"replacement invalidates captured target");}finally{MinecraftForge.EVENT_BUS.unregister(replaced);}h.assertTrue(h.getBlockState(P).is(Blocks.GOLD_BLOCK)&&original.equals(s.save(new CompoundTag())),"replacement not removed, old resource snapshot unchanged");
        h.setBlock(P,Blocks.STONE);var next=charged(100,10,TimeMultitoolSpeedMode.FOUR);Consumer<BlockEvent.BreakEvent> swap=e->{if(e.getPlayer()==p)p.setItemInHand(InteractionHand.MAIN_HAND,next);};MinecraftForge.EVENT_BUS.addListener(swap);try{h.assertTrue(!p.gameMode.destroyBlock(h.absolutePos(P)),"held identity change aborts");}finally{MinecraftForge.EVENT_BUS.unregister(swap);}h.assertTrue(fe(next)==100&&fluid(next)==10&&original.equals(s.save(new CompoundTag()))&&h.getBlockState(P).is(Blocks.STONE),"old/new tools and world remain uncharged");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void recursiveBreakRequestsDoNotTickOrChargeAnotherBlock(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);var p=actor(h,s);h.setBlock(P,Blocks.STONE);h.setBlock(P.east(),Blocks.STONE);boolean[] nested={true};Consumer<BlockEvent.BreakEvent> recurse=e->{if(e.getPlayer()==p)nested[0]=p.gameMode.destroyBlock(h.absolutePos(P.east()));};MinecraftForge.EVENT_BUS.addListener(recurse);try{p.gameMode.destroyBlock(h.absolutePos(P));}finally{MinecraftForge.EVENT_BUS.unregister(recurse);}h.assertTrue(!nested[0]&&h.getBlockState(P.east()).is(Blocks.STONE)&&fe(s)==950&&fluid(s)==98,"recursive call rejected, one original payment/removal");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void leaseRollbackLocksBothResourcesAndOldLeaseCannotUnlockNewLease(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);var original=s.save(new CompoundTag());var owner=TimeMultitoolResources.of(s);var lease=owner.reserve(50,2);h.assertTrue(lease!=null&&fe(s)==950&&fluid(s)==98,"atomic reservation");h.assertTrue(s.getCapability(ForgeCapabilities.ENERGY).orElseThrow(AssertionError::new).receiveEnergy(10,false)==0&&s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElseThrow(AssertionError::new).drain(10,IFluidHandler.FluidAction.EXECUTE).isEmpty(),"callbacks cannot mutate reserved resources");lease.close();h.assertTrue(original.equals(s.save(new CompoundTag())),"rollback restores exact resource tags");try(var next=owner.reserve(50,2)){lease.commit();h.assertTrue(owner.reserve(1,1)==null,"old finished lease cannot unlock a later reservation");next.commit();}h.assertTrue(fe(s)==950&&fluid(s)==98,"committed lease cannot refund twice");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void realBreakSpeedUsesWholeBatchAndFluidOnlyForSuccessfulMining(GameTestHelper h){
        var s=charged(1000,16,TimeMultitoolSpeedMode.SIXTEEN);var p=actor(h,s);h.setBlock(P,Blocks.STONE);var event=new net.minecraftforge.event.entity.player.PlayerEvent.BreakSpeed(p,h.getBlockState(P),5,h.absolutePos(P));TimeMultitoolMiningEvents.onBreakSpeed(event);h.assertTrue(event.getNewSpeed()==80&&fe(s)==1000&&fluid(s)==16,"speed event scales16x without mutating resources");p.gameMode.destroyBlock(h.absolutePos(P));h.assertTrue(fe(s)==950&&fluid(s)==0,"actual completed block consumes selected16mB");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void wrongFluidAndSimulationNegativeCallsCannotMutateOwner(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);var e=s.getCapability(ForgeCapabilities.ENERGY).orElseThrow(AssertionError::new);var f=s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElseThrow(AssertionError::new);var before=s.save(new CompoundTag());h.assertTrue(f.fill(new FluidStack(net.minecraft.world.level.material.Fluids.WATER,100),IFluidHandler.FluidAction.EXECUTE)==0,"only actual Time Fluid accepted");e.extractEnergy(-1,false);e.receiveEnergy(-1,false);f.drain(-1,IFluidHandler.FluidAction.EXECUTE);f.fill(new FluidStack(Registration.TIME_FLUID_SOURCE.get(),10),IFluidHandler.FluidAction.SIMULATE);f.drain(20,IFluidHandler.FluidAction.SIMULATE);e.extractEnergy(20,true);h.assertTrue(before.equals(s.save(new CompoundTag())),"negative/simulated calls leave exact full NBT unchanged");java.util.concurrent.CompletableFuture.runAsync(()->{e.extractEnergy(20,false);f.drain(20,IFluidHandler.FluidAction.EXECUTE);}).join();h.assertTrue(before.equals(s.save(new CompoundTag())),"wrong-thread FE/fluid mutation rejected");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void capacityBoundariesAndTankRefillUseActualForgeCapabilities(GameTestHelper h){
        var s=charged(Integer.MAX_VALUE,Integer.MAX_VALUE,TimeMultitoolSpeedMode.ONE);h.assertTrue(fe(s)==500000&&fluid(s)==1000000,"source exact capacities clamp incoming int max");s.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElseThrow(AssertionError::new).drain(200,IFluidHandler.FluidAction.EXECUTE);var tank=new ItemStack(JDTEItems.BIG_FLUID_TANK.get());tank.getOrCreateTag().putInt("JDTEBigFluidTankFillMode",BigFluidTankItem.FillMode.JDTE_ONLY.ordinal());tank.getCapability(ForgeCapabilities.FLUID_HANDLER_ITEM).orElseThrow(AssertionError::new).fill(new FluidStack(Registration.TIME_FLUID_SOURCE.get(),200),IFluidHandler.FluidAction.EXECUTE);var p=actor(h,s);p.getInventory().setItem(1,tank);JDTEItems.BIG_FLUID_TANK.get().inventoryTick(tank,h.getLevel(),p,1,false);h.assertTrue(fluid(s)==999900&&FluidContainingItem.getAvailableFluid(tank)==100,"real existing large tank moves exactly100mB into new JDTE tool");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void unloadedAndProtectedTargetsCannotBeAccessed(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);upgrade(s,Ability.OREMINER);var p=actor(h,s);var far=new BlockPos(9000000,100,9000000);h.assertTrue(!TimeMultitoolTargets.loaded(h.getLevel(),far),"fixture chunk begins absent");h.assertTrue(tool().getBreakBlockPositions(s,h.getLevel(),far,p,Blocks.DIAMOND_ORE.defaultBlockState()).isEmpty()&&!p.gameMode.destroyBlock(far)&&!TimeMultitoolTargets.loaded(h.getLevel(),far)&&fe(s)==1000,"no unloaded chunk query creates a target or FE payment");p.gameMode.changeGameModeForPlayer(GameType.ADVENTURE);h.setBlock(P,Blocks.STONE);h.assertTrue(!p.gameMode.destroyBlock(h.absolutePos(P))&&h.getBlockState(P).is(Blocks.STONE)&&fe(s)==1000,"adventure permissions prevent removal");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void hoeTransformationUsesForgeHookAndKeepsFluid(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);var p=actor(h,s);h.setBlock(P,Blocks.DIRT);h.setBlock(P.above(),Blocks.AIR);var pos=h.absolutePos(P);var ctx=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));h.assertTrue(tool().useOn(ctx).consumesAction()&&h.getBlockState(P).is(Blocks.FARMLAND)&&fe(s)==999&&fluid(s)==100,"actual hoe modification costs native1FE and no mining fluid");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void sourceRecipeProducesFreshToolAndNoInventedWandUpgrade(GameTestHelper h){
        var recipe=h.getLevel().getRecipeManager().byKey(new net.minecraft.resources.ResourceLocation("jdte","time_multitool")).orElseThrow();var menu=new net.minecraft.world.inventory.AbstractContainerMenu(null,1){public ItemStack quickMoveStack(net.minecraft.world.entity.player.Player p,int i){return ItemStack.EMPTY;}public boolean stillValid(net.minecraft.world.entity.player.Player p){return true;}};var grid=new net.minecraft.world.inventory.TransientCraftingContainer(menu,3,3);var paxel=new ItemStack(Registration.EclipseAlloyPaxel.get());paxel.getOrCreateTag().putInt("Energy",12345);grid.setItem(0,paxel);grid.setItem(1,new ItemStack(JDTEItems.BIG_FLUID_TANK.get()));grid.setItem(2,new ItemStack(JDTEItems.TIME_FLUID_CATALYST.get()));var result=((net.minecraft.world.item.crafting.CraftingRecipe)recipe).assemble(grid,h.getLevel().registryAccess());h.assertTrue(result.is(JDTEItems.TIME_MULTITOOL.get())&&fe(result)==0&&fluid(result)==0&&TimeMultitoolItem.getSelectedSpeedMode(result)==TimeMultitoolSpeedMode.ONE,"pinned vanilla shapeless result is fresh, not a fabricated preserving/wand recipe");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void nativeLeafAndLawnPathsRemainPermissionAwareWithoutMiningFluid(GameTestHelper h){
        var s=charged(5000,100,TimeMultitoolSpeedMode.TWO);upgrade(s,Ability.LEAFBREAKER);upgrade(s,Ability.LAWNMOWER);var p=actor(h,s);h.setBlock(P,Blocks.OAK_LEAVES);var pos=h.absolutePos(P);var ctx=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));h.assertTrue(AbilityMethods.leafbreaker(ctx)&&h.getBlockState(P).isAir()&&fluid(s)==100,"actual native leaf binding dispatches safe source utility with no Time Fluid fee");h.setBlock(P,Blocks.GRASS);Consumer<BlockEvent.BreakEvent> denied=e->{if(e.getPlayer()==p)e.setCanceled(true);};int before=fe(s);MinecraftForge.EVENT_BUS.addListener(denied);try{AbilityMethods.lawnmower(h.getLevel(),p,s,h.absolutePos(P.below()));}finally{MinecraftForge.EVENT_BUS.unregister(denied);}h.assertTrue(h.getBlockState(P).is(Blocks.GRASS)&&fe(s)==before&&fluid(s)==100,"native lawn binding respects real denied events and charges no failed work");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void allTenNativeSmithingAbilitiesRetainToolData(GameTestHelper h){
        var s=charged(12345,1234,TimeMultitoolSpeedMode.SIXTEEN);s.setHoverName(net.minecraft.network.chat.Component.literal("Smithing keeps data"));int count=0;
        for(var ability:tool().getAbilities()) {var key=new net.minecraft.resources.ResourceLocation("jdte","time_multitool_"+ability.getName());var recipe=(net.minecraft.world.item.crafting.SmithingRecipe)h.getLevel().getRecipeManager().byKey(key).orElseThrow();var input=new net.minecraft.world.SimpleContainer(ItemStack.EMPTY,s,new ItemStack(ability.getUpgradeItem()));h.assertTrue(recipe.matches(input,h.getLevel()),"actual native recipe matches new tool and card "+ability);var output=recipe.assemble(input,h.getLevel().registryAccess());h.assertTrue(output.is(JDTEItems.TIME_MULTITOOL.get())&&ToggleableTool.hasUpgrade(output,ability)&&fe(output)==12345&&fluid(output)==1234&&TimeMultitoolItem.getSelectedSpeedMode(output)==TimeMultitoolSpeedMode.SIXTEEN&&output.getHoverName().equals(s.getHoverName()),"native smithing keeps all resources/mode/name while adding "+ability);input.setItem(1,output);h.assertTrue(recipe.assemble(input,h.getLevel().registryAccess()).isEmpty(),"same ability cannot install twice");count++;}
        h.assertTrue(count==10,"all ten original native abilities have real usable upgrade recipes");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void inheritedNeoPaxelActionsAndCancelledForgePlacementConserveFe(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.FOUR);var p=actor(h,s);var pos=h.absolutePos(P);h.setBlock(P,Blocks.OAK_LOG);var ctx=new UseOnContext(p,InteractionHand.MAIN_HAND,new BlockHitResult(Vec3.atCenterOf(pos),Direction.UP,pos,false));h.assertTrue(s.useOn(ctx).consumesAction()&&h.getBlockState(P).is(Blocks.STRIPPED_OAK_LOG)&&fe(s)==999&&fluid(s)==100,"real Forge axe action inherited from pinned Neo BasePaxel is implemented");h.setBlock(P,Blocks.WAXED_COPPER_BLOCK);h.assertTrue(s.useOn(ctx).consumesAction()&&h.getBlockState(P).is(Blocks.COPPER_BLOCK)&&fe(s)==998,"wax-off transformation and one native FE");h.setBlock(P,Blocks.OAK_LOG);var before=s.save(new CompoundTag());Consumer<BlockEvent.EntityPlaceEvent> denied=e->{if(e.getEntity()==p)e.setCanceled(true);};MinecraftForge.EVENT_BUS.addListener(denied);try{s.useOn(ctx);}finally{MinecraftForge.EVENT_BUS.unregister(denied);}h.assertTrue(h.getBlockState(P).is(Blocks.OAK_LOG)&&before.equals(s.save(new CompoundTag())),"actual Forge placement snapshot cancellation rolls back world and dynamic FE/NBT");h.succeed();
    }
    @GameTest(template="mineral_empty") public static void nativeBlockBreakerUsesOnePaidTransactionAndRejectsStaleMachine(GameTestHelper h){
        var s=charged(1000,100,TimeMultitoolSpeedMode.TWO);var p=(net.minecraftforge.common.util.FakePlayer)actor(h,s);h.setBlock(P,Blocks.STONE);var machinePos=h.absolutePos(P.offset(0,0,2));h.getLevel().setBlockAndUpdate(machinePos,Registration.BlockBreakerT1.get().defaultBlockState());var machine=(com.direwolf20.justdirethings.common.blockentities.BlockBreakerT1BE)h.getLevel().getBlockEntity(machinePos);machine.getMachineHandler().setStackInSlot(0,s);
        h.assertTrue(machine.tryBreakBlock(s,p,h.absolutePos(P),h.getBlockState(P))&&h.getBlockState(P).isAir()&&fe(s)==950&&fluid(s)==98,"actual native machine/FakePlayer tool call shares exactly one removal/payment, without legacy second pass");h.getLevel().removeBlockEntity(machinePos);h.setBlock(P,Blocks.STONE);h.assertTrue(!machine.tryBreakBlock(s,p,h.absolutePos(P),h.getBlockState(P))&&fe(s)==950&&fluid(s)==98,"detached machine cannot mutate the target or held resources");h.succeed();
    }
}
